const berlinNow = () => new Date().toLocaleString('en-GB', { timeZone: 'Europe/Berlin' });

// Convert raw seconds (e.g. "358868 seconds" or 358868) to "4d 3h 41m"
function formatUptime(raw) {
    const secs = parseInt(String(raw).replace(/[^0-9]/g, ''), 10);
    if (isNaN(secs) || secs === 0) return String(raw);
    const d = Math.floor(secs / 86400);
    const h = Math.floor((secs % 86400) / 3600);
    const m = Math.floor((secs % 3600) / 60);
    let parts = [];
    if (d > 0) parts.push(d + 'd');
    if (h > 0) parts.push(h + 'h');
    parts.push(m + 'm');
    return parts.join(' ');
}

// Add commas to large numbers: 6217 -> "6,217"
function formatNumber(raw) {
    const num = parseInt(String(raw).replace(/[^0-9]/g, ''), 10);
    if (isNaN(num)) return String(raw);
    return num.toLocaleString('en-US');
}

const state = flow.get('mqttOverview') || {
    statusText: 'Waiting for broker updates',
    statusClass: 'neutral',
    clients: '-',
    rate: '-',
    total: '-',
    uptime: '-',
    updatedAt: berlinNow(),
};

// Map Node-RED i18n status keys to human-readable labels
function humanStatus(text) {
    if (!text) return 'waiting for connection';
    var map = {
        'node-red:common.status.connected': 'Connected',
        'node-red:common.status.disconnected': 'Disconnected',
        'node-red:common.status.connecting': 'Connecting',
        'node-red:common.status.error': 'Error'
    };
    return map[text] || text;
}

// Use endsWith() for topic matching so $SYS prefix is handled correctly.
// MQTT-in nodes subscribe to e.g. $SYS/broker/clients/connected, and
// msg.topic contains the full topic including the $SYS prefix.
var topic = (msg.topic || '');

if (msg.bootstrap) {
    state.updatedAt = berlinNow();
} else if (msg.status) {
    const fill = msg.status.fill || 'grey';
    const stateMap = { green:'good', blue:'good', yellow:'warning', red:'danger', grey:'neutral' };
    state.statusClass = stateMap[fill] || 'neutral';
    state.statusText = humanStatus(msg.status.text);
    state.updatedAt = berlinNow();
} else if (topic.endsWith('/broker/clients/connected')) {
    state.clients = String(msg.payload);
    state.updatedAt = berlinNow();
} else if (topic.endsWith('/broker/load/messages/received/1min')) {
    state.rate = String(msg.payload);
    state.updatedAt = berlinNow();
} else if (topic.endsWith('/broker/messages/received')) {
    // Format immediately: 6217 -> "6,217"
    state.total = formatNumber(msg.payload);
    state.updatedAt = berlinNow();
} else if (topic.endsWith('/broker/uptime')) {
    // Format immediately: "358868 seconds" -> "4d 3h 41m"
    state.uptime = formatUptime(msg.payload);
    state.updatedAt = berlinNow();
}

// Fallback: if uptime still contains "seconds" (old cached value), reformat it
if (state.uptime && String(state.uptime).indexOf('seconds') !== -1) {
    state.uptime = formatUptime(state.uptime);
}
// Fallback: if total is a plain number string with no comma, reformat it
if (state.total && /^\d{4,}$/.test(String(state.total))) {
    state.total = formatNumber(state.total);
}

flow.set('mqttOverview', state);
msg.payload = state;
return msg;

const berlinNow = () => new Date().toLocaleString('en-GB', { timeZone: 'Europe/Berlin' });
const output = String(msg.payload || '');
const parsed = {};

for (const line of output.split(/\r?\n/)) {
    const separator = line.indexOf('=');
    if (separator === -1) {
        continue;
    }

    const key = line.slice(0, separator).trim();
    const value = line.slice(separator + 1).trim();

    if (key) {
        parsed[key] = value;
