}

const daysLeft = Number.parseInt(parsed.days_left || '', 10);
let statusClass = 'neutral';
let statusText = 'Status unavailable';
let statusReason = parsed.status_reason || 'Waiting for certificate status output.';

if (parsed.state === 'healthy') {
    statusClass = 'good';
    statusText = 'Healthy' + (Number.isFinite(daysLeft) ? ' (' + daysLeft + ' days left)' : '');
} else if (parsed.state === 'warning') {
    statusClass = 'warning';
    statusText = 'Renew soon' + (Number.isFinite(daysLeft) ? ' (' + daysLeft + ' days left)' : '');
} else if (parsed.state === 'critical') {
    statusClass = 'danger';
    statusText = 'Expires very soon' + (Number.isFinite(daysLeft) ? ' (' + daysLeft + ' days left)' : '');
} else if (parsed.state === 'expired') {
    statusClass = 'danger';
    statusText = 'Expired';
} else if (parsed.state === 'missing') {
    statusClass = 'danger';
    statusText = 'Certificate unavailable';
