// Parse Mosquitto connection log lines into a persistent active-client table.
//
// Important dashboard rule:
// - The preferred identity is the real MQTT ClientId sent during CONNECT.
// - Some Pi clients currently connect without a fixed CONNECT client id, so
//   Mosquitto assigns an auto-* placeholder in the broker log.
// - When that happens, enrich the connection row only from a fresh online Pi
//   heartbeat so stale retained rows cannot rename the wrong live connection.
// - If multiple broker rows resolve to the same preferred Pi identity, collapse
//   them into one dashboard row so an auto-* placeholder and the real client id
//   for the same live device do not appear as duplicates.
//
// This node receives two kinds of input:
// 1. A full tail of /mosquitto/log/mosquitto.log every 60 seconds.
// 2. Live $SYS/broker/log/N notice messages as Mosquitto emits them.
// Flow context keeps long-running clients visible after their original connect
// line scrolls out of the last 5000 log lines.

var berlinNow = function() { return new Date().toLocaleString('en-GB', { timeZone: 'Europe/Berlin' }); };
var nowMs = Date.now();
var raw = String(msg.payload || '');
var lines = raw.split('\n');

// Persistent state survives repeated poll cycles and, with the configured
// localfilesystem context store, Node-RED restarts as well.
var connected = flow.get('mqttActiveConnections') || {};
var pendingListeners = flow.get('mqttPendingConnectionListeners') || {};
var piStatuses = global.get('mqttPiStatuses') || {};

var protoMap = { '2': 'MQTT 3.1', '4': 'MQTT 3.1.1', '5': 'MQTT 5.0' };
var listenerMap = { '1883': 'Internal', '8883': 'TLS', '9001': 'WebSocket', '9002': 'WSS' };

function decorateClientId(clientId) {
    var text = String(clientId || '').trim();
    var autoGenerated = text === '' || /^auto-/i.test(text);

    return {
        clientId: text || 'auto-generated',
        displayClientId: autoGenerated ? ('Auto-generated: ' + (text || 'unknown')) : text,
        isAutoGenerated: autoGenerated
    };
}

function isFreshOnlineStatus(status) {
    if (!status) {
        return false;
    }

    var ageSeconds = Math.floor((nowMs - Number(status.receivedAtMs || 0)) / 1000);

    return status.displayStatus === 'online' || (
        status.status === 'online' &&
        Number(status.receivedAtMs || 0) > 0 &&
        ageSeconds <= 30
    );
}

function findPiStatusMatch(identity, ipAddress) {
    var candidates = Object.keys(piStatuses).map(function(key) {
        return piStatuses[key];
    }).filter(function(status) {
        return isFreshOnlineStatus(status);
    }).sort(function(a, b) {
        return Number(b.receivedAtMs || 0) - Number(a.receivedAtMs || 0);
    });

    for (var i = 0; i < candidates.length; i++) {
        var candidate = candidates[i];
        if (candidate.clientId && candidate.clientId === identity.clientId) {
            return candidate;
        }
    }

    if (identity.isAutoGenerated) {
        for (var j = 0; j < candidates.length; j++) {
            var autoCandidate = candidates[j];
            if (ipAddress && autoCandidate.ipAddress && autoCandidate.ipAddress === ipAddress) {
                return autoCandidate;
            }
        }

        if (candidates.length === 1) {
            return candidates[0];
        }
    }

    return null;
}

function buildConnectionRow(connMatch, listener, piStatus) {
    var ts = parseInt(connMatch[1], 10) * 1000;
    var ipPort = connMatch[2];
    var ipAddress = ipPort.split(':')[0];
    var identity = decorateClientId(connMatch[3]);
    var matchedPiStatus = piStatus || findPiStatusMatch(identity, ipAddress);
    var preferredClientId = matchedPiStatus && matchedPiStatus.clientId ? matchedPiStatus.clientId : identity.clientId;
    var displayClientId = matchedPiStatus && matchedPiStatus.clientId
        ? matchedPiStatus.clientId
        : identity.displayClientId;
    var locationSlug = matchedPiStatus && matchedPiStatus.locationSlug ? matchedPiStatus.locationSlug : null;
    var locationLabel = matchedPiStatus && matchedPiStatus.location ? matchedPiStatus.location : null;

    return {
        clientId: identity.clientId,
        preferredClientId: preferredClientId,
        dedupeKey: preferredClientId || identity.clientId,
        displayClientId: displayClientId,
        isAutoGenerated: identity.isAutoGenerated,
        ip: ipAddress,
        listener: listener || '-',
        protocol: protoMap[connMatch[4]] || 'MQTT',
        keepAlive: connMatch[5],
        connectedAt: new Date(ts).toLocaleString('en-GB', { timeZone: 'Europe/Berlin' }),
        locationSlug: locationSlug,
        locationLabel: locationLabel,
        matchedPiStatusAt: matchedPiStatus ? matchedPiStatus.heartbeatTimestamp : null
    };
}

for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    if (!line) {
        continue;
    }

    // Match: "New connection from IP:PORT on port LISTENER_PORT."
    // Mosquitto logs this before it knows the MQTT ClientId.
    var listenerMatch = line.match(/New connection from ([\d.]+:\d+) on port (\d+)/);
    if (listenerMatch) {
        pendingListeners[listenerMatch[1]] = listenerMap[listenerMatch[2]] || ('Port ' + listenerMatch[2]);
        continue;
    }

    // Match: "New client connected from IP:PORT as CLIENT_ID (pX, cY, kZ[, u'user'])."
    var connMatch = line.match(/^(\d+):\s+New client connected from ([\d.]+:\d+) as (.+?) \(p(\d+), c\d+, k(\d+)[^)]*\)/);
    if (connMatch) {
        var ipPort = connMatch[2];
        var identity = decorateClientId(connMatch[3]);

        connected[identity.clientId] = buildConnectionRow(
            connMatch,
            pendingListeners[ipPort],
            findPiStatusMatch(identity, ipPort.split(':')[0])
        );
        delete pendingListeners[ipPort];
        continue;
    }

    // Match disconnects and session takeovers by ClientId.
    var discMatch = line.match(/Client ([^\s\[]+).*disconnected/);
    if (discMatch) {
        delete connected[discMatch[1]];
        continue;
    }
}

Object.keys(connected).forEach(function(key) {
    var row = connected[key];
    var identity = decorateClientId(row.clientId);
    var matchedPiStatus = findPiStatusMatch(identity, row.ip);

    if (!matchedPiStatus) {
        return;
    }

    row.preferredClientId = matchedPiStatus.clientId || row.preferredClientId || row.clientId;
    row.dedupeKey = row.preferredClientId || row.clientId;
    row.displayClientId = matchedPiStatus.clientId || row.displayClientId;
    row.locationSlug = matchedPiStatus.locationSlug || row.locationSlug || null;
    row.locationLabel = matchedPiStatus.location || row.locationLabel || null;
    row.matchedPiStatusAt = matchedPiStatus.heartbeatTimestamp || row.matchedPiStatusAt || null;
});

var connectionIndexByPreferredId = {};
Object.keys(connected).forEach(function(key) {
    var row = connected[key];
    var dedupeKey = row.dedupeKey || row.preferredClientId || row.clientId;
    var existingKey = connectionIndexByPreferredId[dedupeKey];

    if (!existingKey) {
        connectionIndexByPreferredId[dedupeKey] = key;
        return;
    }

    var existingRow = connected[existingKey];
    var keepCurrent = false;

    if ((existingRow.isAutoGenerated && !row.isAutoGenerated) || (!existingRow.preferredClientId && row.preferredClientId)) {
        keepCurrent = true;
    } else if ((existingRow.connectedAt || '') < (row.connectedAt || '')) {
        keepCurrent = true;
    }

    if (keepCurrent) {
        delete connected[existingKey];
        connectionIndexByPreferredId[dedupeKey] = key;
    } else {
        delete connected[key];
    }
});

var connList = Object.keys(connected).map(function(k) { return connected[k]; });
connList.sort(function(a, b) { return (b.connectedAt || '').localeCompare(a.connectedAt || ''); });

flow.set('mqttActiveConnections', connected);
flow.set('mqttPendingConnectionListeners', pendingListeners);

msg.payload = {
    connections: connList,
    totalActive: connList.length,
    updatedAt: berlinNow(),
    logLines: lines.length
};
return msg;

const berlinNow = () => new Date().toLocaleString('en-GB', { timeZone: 'Europe/Berlin' });
const nowMs = Date.now();
const statuses = flow.get('mqttPiStatuses') || global.get('mqttPiStatuses') || {};

function parsePayload(raw) {
    if (typeof raw === 'string') {
        try {
            return JSON.parse(raw);
        } catch (error) {
            return { raw_message: raw };
        }
    }

    if (raw && typeof raw === 'object') {
        return raw;
    }

    return { raw_message: String(raw || '') };
}

function formatAge(seconds) {
    if (seconds < 60) return seconds + 's';
    const minutes = Math.floor(seconds / 60);
    const remain = seconds % 60;
    if (minutes < 60) return minutes + 'm ' + remain + 's';
    const hours = Math.floor(minutes / 60);
    return hours + 'h ' + (minutes % 60) + 'm';
}

function normalizeUptime(raw) {
    const seconds = parseInt(raw, 10);
    if (isNaN(seconds) || seconds < 0) return '-';
    const days = Math.floor(seconds / 86400);
    const hours = Math.floor((seconds % 86400) / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const parts = [];
    if (days > 0) parts.push(days + 'd');
    if (hours > 0) parts.push(hours + 'h');
    parts.push(minutes + 'm');
    return parts.join(' ');
}

function normalizeMetricValue(raw, suffix) {
    if (raw === null || raw === undefined || raw === '') {
        return '-';
    }

    return suffix ? (String(raw) + suffix) : String(raw);
}

if (msg.topic && msg.topic !== 'poll') {
    const topicMatch = String(msg.topic).match(/^(dev|live)\/location\/([^/]+)\/pi\/status$/);

    if (topicMatch) {
        const env = topicMatch[1];
        const locationSlug = topicMatch[2];
        const payload = parsePayload(msg.payload);
        const heartbeatTimestamp = payload.timestamp || new Date(nowMs).toISOString();
        const key = env + ':' + locationSlug;

        statuses[key] = {
            env,
            location: payload.location || payload.location_name || null,
            locationSlug: payload.location_slug || locationSlug,
            clientId: payload.client_id || payload.location_slug || locationSlug,
            status: String(payload.status || 'unknown').toLowerCase(),
            heartbeatTimestamp,
            receivedAtMs: nowMs,
            uptime: normalizeUptime(payload.uptime_seconds),
            appVersion: payload.app_version || '-',
            ipAddress: payload.ip_address || '-',
            doorStatus: payload.door_status || '-',
            wifiStrength: normalizeMetricValue(payload.wifi_strength, payload.wifi_strength === null || payload.wifi_strength === undefined || payload.wifi_strength === '' ? '' : ' dBm'),
            ramUsage: normalizeMetricValue(payload.ram_usage, payload.ram_usage === null || payload.ram_usage === undefined || payload.ram_usage === '' ? '' : '%'),
            diskUsage: normalizeMetricValue(payload.disk_usage, payload.disk_usage === null || payload.disk_usage === undefined || payload.disk_usage === '' ? '' : '%'),
            temperature: normalizeMetricValue(payload.temperature, payload.temperature === null || payload.temperature === undefined || payload.temperature === '' ? '' : ' C'),
            message: payload.message || '-',
            topic: msg.topic,
            raw: JSON.stringify(payload, null, 2),
        };
    }
}

const rows = Object.keys(statuses).map(function(key) {
    const row = statuses[key];
    const receivedAtMs = Number(row.receivedAtMs || 0);
    const ageSeconds = receivedAtMs > 0 ? Math.floor((nowMs - receivedAtMs) / 1000) : 999999;
    const stale = row.status !== 'offline' && ageSeconds > 30;
    const displayStatus = stale ? 'stale' : row.status;

    return Object.assign({}, row, {
        displayStatus,
        statusClass: displayStatus === 'online' ? 'success' : (displayStatus === 'stale' ? 'warning' : 'danger'),
        ageSeconds,
        ageText: formatAge(ageSeconds),
        heartbeatDisplay: row.heartbeatTimestamp ? new Date(row.heartbeatTimestamp).toLocaleString('en-GB', { timeZone: 'Europe/Berlin' }) : '-',
    });
});

rows.sort(function(a, b) {
    if (a.env !== b.env) return a.env.localeCompare(b.env);
    return a.locationSlug.localeCompare(b.locationSlug);
});

flow.set('mqttPiStatuses', statuses);
global.set('mqttPiStatuses', statuses);

msg.payload = {
    rows,
    total: rows.length,
    online: rows.filter(function(row) { return row.displayStatus === 'online'; }).length,
    stale: rows.filter(function(row) { return row.displayStatus === 'stale'; }).length,
    offline: rows.filter(function(row) { return row.displayStatus === 'offline'; }).length,
    updatedAt: berlinNow(),
};
return msg;
